<script setup>
import { computed, onMounted, reactive } from 'vue'; import { Save } from 'lucide-vue-next'; import { useAuthStore } from '@/stores/auth'; import { useSettingsStore } from '@/stores/settings'; import { useMasterDataStore } from '@/stores/masterData'; import { useUiStore } from '@/stores/ui'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import InvoiceDocument from '@/components/invoice/InvoiceDocument.vue';
const settings=useSettingsStore(),master=useMasterDataStore(),ui=useUiStore(),auth=useAuthStore(),form=reactive({...settings.invoiceTemplate});const readOnly=computed(()=>auth.role==='manager');const demoInvoice={id:'template-demo',number:'001/INV/RKA/VIII/26',name:'Project Spiritra',clientId:'k1',client:'Graha Indonesia Telekomunika',date:'2026-08-01',dueDate:'2026-08-15',accountId:'r1',items:[{id:'demo-item',description:'Pembayaran Ke-2 Pelunasan Project Spiritra',price:3000000,qty:1}],discount:0,terms:'Silakan lakukan pembayaran ke rekening yang tertera di atas'};const controls=[['showLogo','Logo Perusahaan'],['showTagline','Tagline / Deskripsi'],['showTitle','Judul Invoice'],['showNumber','Nomor Invoice'],['showInvoiceDate','Tanggal Invoice'],['showDueDate','Tanggal Jatuh Tempo'],['showClient','Data Klien'],['showItems','Rincian Item'],['showSubtotal','Subtotal'],['showDiscount','Diskon'],['showTotal','Total'],['showBankInfo','Informasi Rekening Bank'],['showTerms','Terms & Conditions'],['showStamp','Cap Perusahaan'],['showSignature','Tanda Tangan'],['showSignerName','Nama Penanda Tangan'],['showSignerPosition','Jabatan Penanda Tangan']];
onMounted(async()=>{await Promise.all([settings.ensure(),master.ensureAll()]);Object.assign(form,settings.invoiceTemplate)});
const save=async()=>{try{await settings.saveTemplate(form);ui.notify('Template berhasil disimpan.')}catch(error){ui.notify(error.response?.data?.message||'Gagal menyimpan template.','error')}};
</script>
<template><div class="p-6"><header class="mb-5 flex justify-between gap-4"><div><h1 class="text-xl font-semibold">Template Invoice</h1><p class="mt-0.5 text-sm text-[#667085]">Konfigurasi tampilan dan elemen invoice yang diterbitkan.</p></div><BaseButton v-if="!readOnly" @click="save"><Save :size="14"/>Simpan Template</BaseButton></header><div class="grid gap-6 xl:grid-cols-5"><BaseCard class="space-y-3 xl:col-span-2" padding="p-5"><h2 class="text-sm font-semibold">Elemen Invoice</h2><BaseInput v-model="form.title" label="Judul Invoice" :disabled="readOnly"/><label v-for="field in controls" :key="field[0]" class="flex items-center justify-between gap-3 text-sm"><span>{{field[1]}}</span><input v-model="form[field[0]]" type="checkbox" :disabled="readOnly"/></label></BaseCard><BaseCard class="xl:col-span-3" padding="p-5"><p class="mb-3 text-center text-xs text-[#667085]">Preview Template</p><div class="overflow-auto"><InvoiceDocument :invoice="demoInvoice" :company="settings.company" :client="master.getClientById('k1')" :payment-account="master.getAccountById('r1')" :template="form" class="mx-auto scale-[.67] origin-top"/></div></BaseCard></div></div></template>
